mapper.update:
UPDATE marketing_task
SET status = 7,
    next_round_at = NULL,
    finished_at = COALESCE(finished_at, #{now}),
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status IN (1, 2, 5)
  AND task_end_at IS NOT NULL
  AND task_end_at <= #{now}

UPDATE marketing_task
SET status = 1,
    next_round_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
  AND task_start_at IS NOT NULL
  AND task_start_at > #{now}

UPDATE marketing_task
SET next_round_at = #{nextRoundAt},
    updated_at = #{now}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = 2
  AND next_round_at IS NOT NULL
  AND next_round_at <= #{now}
  AND (task_end_at IS NULL OR task_end_at > #{now})

UPDATE marketing_task_send_attempt
SET outbox_accepted_at = #{acceptedAt}
WHERE id = #{attemptId}
  AND command_id = #{commandId}
  AND status = 0
  AND outbox_accepted_at IS NULL

UPDATE group_pull_marketing_execution
SET group_status = 2,
    updated_at = #{now}
WHERE marketing_target_id = #{targetId}
  AND group_status = 1

UPDATE marketing_task_target
SET retry_count = retry_count + 1,
    last_attempt_at = #{updatedAt},
    updated_at = #{updatedAt}
WHERE id = #{targetId}
  AND EXISTS (
      SELECT 1
      FROM marketing_task_send_attempt a
      WHERE a.id = #{attemptId}
        AND a.target_id = marketing_task_target.id
        AND a.round_no = 0
        AND a.attempt_no = 2
  )

UPDATE marketing_task
SET target_group_count = target_group_count + 1,
    updated_at = #{now}
WHERE id = #{taskId}

UPDATE marketing_task_send_attempt attempt
JOIN protocol_command_outbox outbox_row
  ON outbox_row.command_id = attempt.command_id
 AND outbox_row.tenant_id = #{tenantId}
 AND outbox_row.status = 4
SET attempt.status = 3,
    attempt.reason_code = 'TASK_RELEASED',
    attempt.reason_message = '任务已结束，发送命令已取消',
    attempt.result_at = #{now}
WHERE attempt.marketing_task_id = #{taskId}
  AND attempt.tenant_id = #{tenantId}
  AND attempt.status = 0

UPDATE marketing_task_send_attempt attempt
JOIN protocol_command_outbox outbox_row
  ON outbox_row.command_id = attempt.command_id
 AND outbox_row.tenant_id = #{tenantId}
 AND outbox_row.status = 3
SET attempt.status = 2,
    attempt.reason_code = 'OUTBOX_DEAD',
    attempt.reason_message = COALESCE(outbox_row.last_error, '协议命令发送失败'),
    attempt.result_at = #{now}
WHERE attempt.marketing_task_id = #{taskId}
  AND attempt.tenant_id = #{tenantId}
  AND attempt.status = 0

mapper.select:
SELECT a.id AS accountId, a.ws_phone AS accountPhone, g.id AS groupLinkId, current_group.group_jid AS groupJid, g.link_url AS groupLinkUrl, COALESCE(NULLIF(TRIM(g.group_name), ''), current_profile.subject, current_group.group_jid) AS groupName, CASE self_participant.presence_status WHEN 1 THEN 1 WHEN 0 THEN 2 WHEN 2 THEN CASE self_participant.last_exit_type WHEN 'REMOVED' THEN 3 WHEN 'LEFT' THEN 4 ELSE 5 END ELSE 2 END AS membershipStatus, COALESCE(self_participant.presence_observed_at, binding.last_observed_at) AS statusUpdatedAt FROM account a JOIN account_state s ON s.account_id = a.id JOIN account_group_sync_state group_sync ON group_sync.account_id = a.id JOIN group_link g ON g.id = #{groupLinkId} AND g.deleted_at IS NULL JOIN wa_group current_group ON current_group.id = g.group_id AND current_group.deleted_at IS NULL JOIN wa_account_group_binding binding ON binding.account_id = a.id AND binding.group_id = current_group.id JOIN wa_group_participant self_participant ON self_participant.group_id = binding.group_id AND self_participant.id = binding.participant_id LEFT JOIN wa_group_profile current_profile ON current_profile.group_id = current_group.id WHERE a.id = #{accountId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND s.login_state = 1 AND s.account_state IN
#{accountState}
AND a.protocol_account_id IS NOT NULL AND TRIM(a.protocol_account_id) <> '' AND group_sync.baseline_state IN (2, 3) AND (s.risk_status IS NULL OR s.risk_status = 1) AND (s.mute_status IS NULL OR s.mute_status = 2) LIMIT 1

SELECT a.id AS accountId, a.ws_phone AS accountPhone FROM account a JOIN account_state s ON s.account_id = a.id JOIN account_group_sync_state group_sync ON group_sync.account_id = a.id WHERE a.id = #{accountId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND s.login_state = 1 AND s.account_state IN
#{accountState}
AND a.protocol_account_id IS NOT NULL AND TRIM(a.protocol_account_id) <> '' AND group_sync.baseline_state IN (2, 3) AND (s.risk_status IS NULL OR s.risk_status = 1) AND (s.mute_status IS NULL OR s.mute_status = 2) LIMIT 1

SELECT a.id AS accountId, a.ws_phone AS accountPhone, g.id AS groupLinkId, current_group.group_jid AS groupJid, g.link_url AS groupLinkUrl, COALESCE(NULLIF(TRIM(g.group_name), ''), current_profile.subject, current_group.group_jid) AS groupName, CASE self_participant.presence_status WHEN 1 THEN 1 WHEN 0 THEN 2 WHEN 2 THEN CASE self_participant.last_exit_type WHEN 'REMOVED' THEN 3 WHEN 'LEFT' THEN 4 ELSE 5 END ELSE 2 END AS membershipStatus, COALESCE(self_participant.presence_observed_at, binding.last_observed_at) AS statusUpdatedAt FROM account a JOIN wa_account_group_binding binding ON binding.account_id = a.id JOIN wa_group current_group ON current_group.id = binding.group_id JOIN wa_group_participant self_participant ON self_participant.group_id = binding.group_id AND self_participant.id = binding.participant_id LEFT JOIN group_link g ON g.group_id = binding.group_id LEFT JOIN wa_group_profile current_profile ON current_profile.group_id = current_group.id WHERE a.id = #{accountId} AND a.deleted_at IS NULL AND a.protocol_account_id IS NOT NULL AND TRIM(a.protocol_account_id) <> '' AND ( #{accountGroupSendAt} IS NULL OR binding.membership_active_since_at >= #{accountGroupSendAt}
OR EXISTS ( SELECT 1 FROM marketing_task_send_attempt first_send WHERE first_send.target_id = #{targetId} AND first_send.round_no = 0 AND TRIM(first_send.group_jid) = TRIM(current_group.group_jid) )
)
AND NOT EXISTS ( SELECT 1 FROM marketing_task_send_attempt delayed_send WHERE delayed_send.target_id = #{targetId} AND delayed_send.round_no = 0 AND delayed_send.scheduled_send_at > delayed_send.detected_at AND TRIM(delayed_send.group_jid) = TRIM(current_group.group_jid) AND ( delayed_send.status = 4
OR delayed_send.attempted_at >= #{ordinaryRoundDueAt}
) )
ORDER BY g.id ASC
